local FX = {   -- by finish: aura, foil, rune brightness, spin, rays, sparks
  [1] = { aura = 0, foil = 0, rune = 0.2 },
  [2] = { aura = 0.3, foil = 0, rune = 0.32 },
  [3] = { aura = 0.42, foil = 0.5, rune = 0.5, spin = true, sparks = true },
